import { test } from '@playwright/test';

import { loginAs } from '../bazis';

import { PRODUCT } from './product';

test('manager-starts-from-the-home', async ({ page }) => {
  const app = await loginAs(page, PRODUCT, 'manager');
  await test.step('open: home', async () => {
    await app.open('home');
  });
  await test.step('expect: {tile: {review: 1, review-hours: 2.5}}', async () => {
    await app.expectTile('review', 1);
    await app.expectTile('review-hours', 2.5);
  });
  await test.step('action: create', async () => {
    await app.action('create');
  });
  await test.step('fill: {title: Plan from the home}', async () => {
    await app.fill({ title: 'Plan from the home' });
  });
  await test.step('submit', async () => {
    await app.submit({ saved: true });
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, status: draft}', async () => {
    await app.expectScreen('task-card');
    await app.expectStatus('draft');
  });
  await test.step('open: home', async () => {
    await app.open('home');
  });
  await test.step('open_item: {in: last-tasks, where: {title: Plan from the home}}', async () => {
    await app.openItem({ in: 'last-tasks', where: { title: 'Plan from the home' }, created: true });
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, status: draft}', async () => {
    await app.expectScreen('task-card');
    await app.expectStatus('draft');
  });
});
